// Localization: loads the same en/vi tables the Unity client uses (public/i18n/*.json, generated by
// tools/build_web_assets.py) and overlays web-only strings from ./web.ts. t(key, ...args) supports {0}-style args.
import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';
import { WEB_STRINGS } from './web';

export type Lang = 'en' | 'vi';
type Table = Record<string, string>;

const LS_LANG = 'petstar.lang';

export function format(s: string, args: (string | number)[]): string {
  return s.replace(/\{(\d+)\}/g, (m, i) => (args[Number(i)] !== undefined ? String(args[Number(i)]) : m));
}

/** Pure lookup used by the provider and by tests. Missing keys fall back to English, then the key itself. */
export function lookup(tables: Partial<Record<Lang, Table>>, lang: Lang, key: string, args: (string | number)[] = []): string {
  const s = tables[lang]?.[key] ?? WEB_STRINGS[lang][key] ?? tables.en?.[key] ?? WEB_STRINGS.en[key] ?? key;
  return format(s, args);
}

interface I18n { lang: Lang; setLang: (l: Lang) => void; t: (key: string, ...args: (string | number)[]) => string; ready: boolean }
const Ctx = createContext<I18n>({ lang: 'en', setLang: () => {}, t: (k) => k, ready: false });

function initialLang(): Lang {
  try { const s = localStorage.getItem(LS_LANG); if (s === 'en' || s === 'vi') return s; } catch { /* ignore */ }
  return navigator.language?.toLowerCase().startsWith('vi') ? 'vi' : 'en';
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(initialLang);
  const [tables, setTables] = useState<Partial<Record<Lang, Table>>>({});
  useEffect(() => {
    const need: Lang[] = lang === 'en' ? ['en'] : ['en', lang];
    need.filter((l) => !tables[l]).forEach((l) =>
      fetch(`${import.meta.env.BASE_URL}i18n/${l}.json`).then((r) => r.json()).then((j: Table) => setTables((t) => ({ ...t, [l]: j }))).catch(() => {}));
    document.documentElement.lang = lang;
  }, [lang, tables]);
  const setLang = useCallback((l: Lang) => { setLangState(l); try { localStorage.setItem(LS_LANG, l); } catch { /* ignore */ } }, []);
  const t = useCallback((key: string, ...args: (string | number)[]) => lookup(tables, lang, key, args), [tables, lang]);
  const value = useMemo(() => ({ lang, setLang, t, ready: !!tables.en }), [lang, setLang, t, tables.en]);
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export const useI18n = () => useContext(Ctx);
export const useT = () => useContext(Ctx).t;
